mapper.select:
select 
from p_avatar_version v join p_avatar a on a.id = v.avatar_id and a.account_id = v.account_id
where v.account_id = #{accountId} and v.avatar_id = #{avatarId} and v.id = #{versionId}

select count(*) from p_app_config c
join p_avatar_version v on v.id = c.avatar_version_id
where v.avatar_id = #{avatarId}

select
  (select count(*) from p_resource_reference r join p_avatar_version v on v.id=r.resource_id
   where r.account_id=#{accountId} and r.resource_type='AVATAR_VERSION' and v.avatar_id=#{avatarId}
     and r.holder_type='APP_CURRENT' and r.state in ('RESERVED','CONFIRMED')) applications,
  (select count(*) from p_resource_reference r join p_avatar_version v on v.id=r.resource_id
   where r.account_id=#{accountId} and r.resource_type='AVATAR_VERSION' and v.avatar_id=#{avatarId}
     and r.holder_type='SESSION' and r.state in ('RESERVED','CONFIRMED')) sessions,
  (select count(*) from p_generation_task t where t.account_id=#{accountId} and t.avatar_id=#{avatarId}
     and t.status in ('QUEUED','PROCESSING')) generations
